                            d = datetime.strptime(date_str, '%Y%m%d').date()
                        else:
                            d = datetime.strptime(date_str, '%Y-%m-%d').date()
                        holidays.add(d)
                    except Exception:
                        continue
    _parsed_dates = holidays
    return _parsed_dates

def is_holiday(date: str) -> bool:
    """True if date is a company holiday per calendars/company_2025.ics."""
    try:
        d = datetime.strptime(date, '%Y-%m-%d').date()
    except Exception:
        return False
    return d in _load_holidays()

def flatten(xs: list) -> list:
    """Flatten an arbitrarily nested list of ints, preserving left-to-right order."""
    result = []
    for item in xs:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result
